fixed_code:
def floors_travelled(start, end):
    # Floors the lift moves between start and end in a building with no floor 0
    return abs(end - start)

def floors_travelled(start, end):
    # Floors moved, with one taken off for the missing floor 0 when crossing between basement and ground floors
    distance = abs(end - start)
    if (start < 0 <= end) or (end < 0 <= start):
        distance -= 1
    return distance

